import json, os

def load(name):
    raw = os.environ.get(name, '') or '{}'
    try:
        return json.loads(raw)
    except Exception:
        return {}

series = load('METRIC_JSON')
trail = load('TRAIL_JSON')

points = []
for p in series.get('Datapoints', []):
    points.append({
        'timestamp': p.get('Timestamp'),
        'average': p.get('Average'),
        'maximum': p.get('Maximum'),
        'unit': p.get('Unit'),
    })
points.sort(key=lambda x: str(x.get('timestamp') or ''))

# Every event is returned, including read-only ones. Whether a call is
# relevant is a judgement, and this returns facts.
events = []
for e in trail.get('Events', []):
    detail = {}
    try:
        detail = json.loads(e.get('CloudTrailEvent') or '{}')
    except Exception:
        pass
    events.append({
        'event_time': e.get('EventTime'),
        'event_name': e.get('EventName'),
        'event_source': e.get('EventSource'),
        'username': e.get('Username'),
        'read_only': detail.get('readOnly'),
        'source_ip': detail.get('sourceIPAddress'),
        'user_agent': (detail.get('userAgent') or '')[:160],
        'error_code': detail.get('errorCode'),
        'request_parameters': detail.get('requestParameters'),
        'resources': [r.get('ResourceName') for r in (e.get('Resources') or [])],
    })
events.sort(key=lambda x: str(x.get('event_time') or ''))

print(json.dumps({
    'resource': os.environ.get('RESOURCE', ''),
    'metric_name': os.environ.get('METRIC_NAME', ''),
    'namespace': os.environ.get('NAMESPACE', ''),
    'window_start': os.environ.get('WINDOW_START', ''),
    'window_end': os.environ.get('WINDOW_END', ''),
    'datapoint_count': len(points),
    'datapoints': points,
    'api_event_count': len(events),
    'api_events': events,
}, default=str))

